export interface Candidate {
  id: string;
  displayName: string;
}

export class CandidateList {
  private readonly candidates: Candidate[];

  constructor(
    candidates: readonly Candidate[],
    private readonly onPick: (id: string) => void
  ) {
    if (!Array.isArray(candidates) || typeof onPick !== "function") {
      throw new TypeError("invalid constructor arguments");
    }
    const ids = new Set<string>();
    this.candidates = candidates.map((candidate, index) => {
      if (typeof candidate.id !== "string" || candidate.id.trim().length === 0) {
        throw new TypeError(`invalid id at index ${index}`);
      }
      if (typeof candidate.displayName !== "string" || candidate.displayName.trim().length === 0) {
        throw new TypeError(`invalid displayName at index ${index}`);
      }
      if (ids.has(candidate.id)) throw new TypeError(`duplicate id: ${candidate.id}`);
      ids.add(candidate.id);
      return { id: candidate.id, displayName: candidate.displayName };
    });
  }

  entries(): Candidate[] {
    return this.candidates.map(candidate => ({ ...candidate }));
  }

  pick(id: string): boolean {
    const candidate = this.candidates.find(entry => entry.id === id);
    if (!candidate) return false;
    this.onPick(candidate.displayName);
    return true;
  }
}

