import { CandidateList } from './solution';
import type { Candidate } from './solution';

function ok(value: boolean, message: string): void {
  if (!value) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function throwsTypeError(fn: () => void, message: string): void {
  try {
    fn();
  } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const source: Candidate[] = [
  { id: ' Alpha ', displayName: ' Same Name ' },
  { id: 'alpha', displayName: ' Same Name ' },
  { id: 'beta', displayName: 'Beta' }
];
const picked: string[] = [];
const list = new CandidateList(source, id => picked.push(id));
source[0].id = 'changed';
source[0].displayName = 'changed';
source.push({ id: 'later', displayName: 'Later' });

const entries = list.entries();
equal(JSON.stringify(entries), JSON.stringify([
  { id: ' Alpha ', displayName: ' Same Name ' },
  { id: 'alpha', displayName: ' Same Name ' },
  { id: 'beta', displayName: 'Beta' }
]), 'constructor copies data and preserves order, strings, and duplicate names');
entries[0].id = 'mutated';
entries.pop();
equal(list.entries()[0].id, ' Alpha ', 'entries returns fresh objects');
equal(list.entries().length, 3, 'entries returns a fresh array');

ok(list.pick(' Alpha '), 'exact ID matches');
equal(picked.join(','), ' Alpha ', 'callback receives exact preserved ID once');
ok(!list.pick('Alpha'), 'case and whitespace differences do not match');
ok(list.pick('alpha'), 'case-sensitive second ID matches');
ok(!list.pick(''), 'empty unknown ID returns false');
ok(!list.pick('missing'), 'unknown ID returns false');
equal(picked.join(','), ' Alpha ,alpha', 'unknown IDs do not invoke callback');

const empty = new CandidateList([], () => { throw new Error('must not be called'); });
equal(empty.entries().length, 0, 'empty candidate list is valid');
ok(!empty.pick('anything'), 'empty list has no matches');

throwsTypeError(() => new CandidateList([{ id: '', displayName: 'Name' }], () => undefined), 'empty ID');
throwsTypeError(() => new CandidateList([{ id: '\t ', displayName: 'Name' }], () => undefined), 'blank ID');
throwsTypeError(() => new CandidateList([{ id: 'id', displayName: '\n' }], () => undefined), 'blank display name');
throwsTypeError(() => new CandidateList([{ id: 2 as unknown as string, displayName: 'Name' }], () => undefined), 'non-string ID');
throwsTypeError(() => new CandidateList([{ id: 'id', displayName: null as unknown as string }], () => undefined), 'non-string display name');
throwsTypeError(() => new CandidateList([
  { id: 'same', displayName: 'One' },
  { id: 'same', displayName: 'Two' }
], () => undefined), 'duplicate IDs');

